// CONFIG: edit this list to add or remove tickers
const tickers = ['SPY', 'NVDA', 'AMZN', 'MSTR', 'BN', 'GOOGL', 'GLD'];

return tickers.map(t => ({ json: { ticker: t } }));

// ===== DATA =====
const btc = $('CoinGecko').first().json.bitcoin;
const tickers = $('Ticker Config').all().map(i => i.json.ticker);
const quotes = $('Finnhub').all().map(i => i.json);

// ===== HELPERS =====
const usd = n => n.toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const pct = n => (n == null ? 'n/a' : `${n >= 0 ? '+' : ''}${n.toFixed(2)}%`);
const color = n => (n == null ? '#6b7280' : n >= 0 ? '#16a34a' : '#dc2626');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const td = 'padding:8px 12px;border-bottom:1px solid #e5e7eb;';
const tdRight = td + 'text-align:right;';

// ===== PRICE TABLE =====
const row = (name, price, change) => `
  <tr>
    <td style="${td}font-weight:600;">${name}</td>
    <td style="${tdRight}">${price == null ? 'no data' : usd(price)}</td>
    <td style="${tdRight}color:${color(change)};font-weight:600;">${pct(change)}</td>
  </tr>`;

const rows = [row('BTC', btc.usd, btc.usd_24h_change)];
quotes.forEach((q, i) => {
  rows.push(q.c ? row(tickers[i], q.c, q.dp) : row(tickers[i], null, null));
});

// ===== MACRO BULLETS FROM CLAUDE =====
let bullets = [];
try {
  const blocks = $('Claude').first().json.content || [];
  const text = blocks
    .filter(b => b.type === 'text')
    .map(b => b.text)
    .join('\n');

  bullets = text
    .split('\n')
    .map(l => l.replace(/^[-•*]\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 3);
} catch (e) {
  bullets = [];
}

const macroHtml = bullets.length
  ? bullets.map(b => `<p style="margin:0 0 8px;">• ${esc(b)}</p>`).join('')
  : `<p style="color:#6b7280;margin:0;">Macro headlines unavailable today.</p>`;

// ===== ASSEMBLE EMAIL =====
const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#111827;max-width:560px;">
  <h2 style="margin:0 0 12px;">Morning Brief, ${dateStr}</h2>
  <table style="border-collapse:collapse;min-width:360px;">
    <thead>
      <tr style="background:#f3f4f6;">
        <th style="${td}text-align:left;">Asset</th>
        <th style="${tdRight}">Price</th>
        <th style="${tdRight}">Change</th>
      </tr>
    </thead>
    <tbody>${rows.join('')}</tbody>
  </table>
  <p style="font-size:12px;color:#6b7280;margin:8px 0 20px;">BTC change is 24h. Stock change is vs. previous close.</p>

  <h3 style="margin:0 0 8px;">Macro Watch</h3>
  ${macroHtml}
  <p style="font-size:11px;color:#9ca3af;margin-top:16px;">Summary generated by Claude from Finnhub headlines.</p>
</div>`;

return [{ json: { subject: `Morning Brief — ${dateStr}`, message: html } }];

// Keep only the last 24 hours of news
const cutoff = Date.now() / 1000 - 24 * 3600;
const news = $input.all().map(i => i.json).filter(n => n.datetime >= cutoff);

// Macro keywords: rates, jobs, inflation, oil, etc.
const macro = /\b(fed|fomc|powell|rate|rates|inflation|cpi|pce|jobs|payroll|unemployment|oil|opec|crude|treasury|yield|recession|gdp|tariff)\b/i;
const macroNews = news.filter(n => macro.test(`${n.headline} ${n.summary}`));

// Fall back to general news if it's a slow macro day
const picked = (macroNews.length >= 5 ? macroNews : news).slice(0, 20);

const headlines = picked
  .map((n, i) => `${i + 1}. ${n.headline} (${n.source})`)
  .join('\n');

return [{ json: { headlines, count: picked.length } }];

