={{ JSON.stringify({
  model: "claude-haiku-5-5",
  max_tokens: 1000,
  output_config: { effort: "low" },
  system: "You write a morning macro brief for a retail investor who holds BTC, MSTR, NVDA, AMZN, BN, BMNR, GLD and SPY. Summarize the headlines into exactly 3 bullets covering the most market-relevant macro news (rates/Fed, jobs, inflation, oil, policy). Each bullet is one sentence, max 30 words. Output only the 3 bullets, each on its own line starting with '- '. No intro, no outro.",
  messages: [{ role: "user", content: "Headlines from the last 24 hours:\n\n" + $json.headlines }]
}) }}
